def transform(grid):
    from collections import Counter, deque

    H, W = len(grid), len(grid[0])

    def panel_candidates():
        # Each candidate is a two-color rectangular panel and the region
        # containing the pieces to be placed in it.
        for axis, length in (("v", W), ("h", H)):
            for k in range(1, length):
                for panel_before in (True, False):
                    if axis == "v":
                        if panel_before:
                            panel = [row[:k] for row in grid]
                            source = [row[k:] for row in grid]
                        else:
                            panel = [row[k:] for row in grid]
                            source = [row[:k] for row in grid]
                    else:
                        if panel_before:
                            panel, source = grid[:k], grid[k:]
                        else:
                            panel, source = grid[k:], grid[:k]

                    colors = set(v for row in panel for v in row)
                    if len(colors) != 2 or len(panel) < 2 or len(panel[0]) < 2:
                        continue

                    # The panel's background is the color most common on its border.
                    border = []
                    ph, pw = len(panel), len(panel[0])
                    for c in range(pw):
                        border.append(panel[0][c])
                        border.append(panel[ph - 1][c])
                    for r in range(1, ph - 1):
                        border.append(panel[r][0])
                        border.append(panel[r][pw - 1])
                    base = Counter(border).most_common(1)[0][0]
                    mask = {
                        (r, c)
                        for r in range(ph) for c in range(pw)
                        if panel[r][c] != base
                    }

                    flat_source = [v for row in source for v in row]
                    if not flat_source:
                        continue
                    source_bg = Counter(flat_source).most_common(1)[0][0]

                    # Extract 4-connected source objects, including multicolor objects.
                    sh, sw = len(source), len(source[0])
                    seen = set()
                    objects = []
                    for r in range(sh):
                        for c in range(sw):
                            if source[r][c] == source_bg or (r, c) in seen:
                                continue
                            q = deque([(r, c)])
                            seen.add((r, c))
                            cells = []
                            while q:
                                y, x = q.popleft()
                                cells.append((y, x, source[y][x]))
                                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                                    yy, xx = y + dy, x + dx
                                    if (0 <= yy < sh and 0 <= xx < sw
                                            and (yy, xx) not in seen
                                            and source[yy][xx] != source_bg):
                                        seen.add((yy, xx))
                                        q.append((yy, xx))
                            r0 = min(y for y, x, v in cells)
                            r1 = max(y for y, x, v in cells)
                            c0 = min(x for y, x, v in cells)
                            c1 = max(x for y, x, v in cells)
                            objects.append({
                                "h": r1 - r0 + 1,
                                "w": c1 - c0 + 1,
                                "cells": [(y - r0, x - c0, v) for y, x, v in cells],
                            })

                    if not objects or sum(o["h"] * o["w"] for o in objects) != len(mask):
                        continue

                    # Possible placements of each object's bounding rectangle,
                    # restricted to the panel's mask cells.
                    placements = []
                    by_cell = {}
                    for i, obj in enumerate(objects):
                        h, w = obj["h"], obj["w"]
                        for r in range(ph - h + 1):
                            for c in range(pw - w + 1):
                                rect = frozenset(
                                    (y, x)
                                    for y in range(r, r + h)
                                    for x in range(c, c + w)
                                )
                                if rect <= mask:
                                    p = (i, r, c, rect)
                                    pi = len(placements)
                                    placements.append(p)
                                    for cell in rect:
                                        by_cell.setdefault(cell, []).append(pi)

                    # Exact-cover search: use every object once and cover the mask.
                    full_unused = (1 << len(objects)) - 1
                    memo = set()

                    def search(rem, unused):
                        if not rem:
                            return () if unused == 0 else None
                        if unused == 0:
                            return None
                        key = (frozenset(rem), unused)
                        if key in memo:
                            return None
                        memo.add(key)

                        best_options = None
                        for cell in rem:
                            opts = []
                            for pi in by_cell.get(cell, ()):
                                i, r, c, rect = placements[pi]
                                if (unused >> i) & 1 and rect <= rem:
                                    opts.append(pi)
                            if not opts:
                                return None
                            if best_options is None or len(opts) < len(best_options):
                                best_options = opts
                                if len(opts) == 1:
                                    break

                        best_options.sort(
                            key=lambda pi: -objects[placements[pi][0]]["h"]
                                             * objects[placements[pi][0]]["w"]
                        )
                        for pi in best_options:
                            i, r, c, rect = placements[pi]
                            tail = search(rem - rect, unused ^ (1 << i))
                            if tail is not None:
                                return (pi,) + tail
                        return None

                    solution = search(mask, full_unused)
                    if solution is None:
                        continue

                    out = [[base for _ in range(pw)] for _ in range(ph)]
                    for pi in solution:
                        i, r, c, rect = placements[pi]
                        for dy, dx, value in objects[i]["cells"]:
                            out[r + dy][c + dx] = value

                    border_ratio = Counter(border)[base] / len(border)
                    yield (border_ratio, ph * pw, out)

    candidates = list(panel_candidates())
    if candidates:
        candidates.sort(key=lambda item: (item[0], item[1]), reverse=True)
        return candidates[0][2]
    return [row[:] for row in grid]
